content.a:expression:
a!dashboardLayout(
  contents: {
    a!cardLayout(
      contents: {
        a!richTextDisplayField(
          value: {
            a!richTextItem(text: "Employee Analytics Dashboard", style: "HEADER_MEDIUM")
          }
        )
      }
    ),
    a!columnsLayout(
      columns: {
        a!columnLayout(
          contents: {
            a!readOnlyGridField(
              label: "Employee Directory",
              data: ri!employees,
              columns: {
                a!gridColumn(label: "ID", value: fv!row.id),
                a!gridColumn(label: "Name", value: concat(fv!row.firstName, " ", fv!row.lastName)),
                a!gridColumn(label: "Department", value: fv!row.department),
                a!gridColumn(label: "Status", value: fv!row.status),
                a!gridColumn(label: "Salary ($)", value: fv!row.salary)
              }
            )
          }
        )
      }
    )
  }
)
